package com.wizzadrds.theworldremembers.voice; import java.io.*;import java.nio.file.*; public final class LocalTextToSpeech{private final Path executable;public LocalTextToSpeech(Path executable){this.executable=executable;}public Path synthesize(String text,Path output)throws IOException,InterruptedException{if(text==null||text.isBlank())throw new IllegalArgumentException();Path parent=output.toAbsolutePath().getParent();if(parent!=null)Files.createDirectories(parent);Process p=new ProcessBuilder(executable.toString(),text,output.toAbsolutePath().toString()).redirectErrorStream(true).start();int code=p.waitFor();if(code!=0)throw new IOException("Local TTS exited with "+code);return output;}}